import{_ as r,o,c as t,a5 as i}from"./chunks/framework.DJo0M80U.js";const S=JSON.parse('{"title":"浏览器消息推送","description":"浏览器消息推送，也称为 Web 推送通知，是一种能让网站向用户即时发送信息的技术，即使用户没有打开该网站的页面。这种技术主要依赖于浏览器的 Service Worker 和 Push API。下面详细介绍其工作原理： 1. 注册 Service Worker： Service W。","frontmatter":{"title":"浏览器消息推送","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"浏览器消息推送，也称为 Web 推送通知，是一种能让网站向用户即时发送信息的技术，即使用户没有打开该网站的页面。这种技术主要依赖于浏览器的 Service Worker 和 Push API。下面详细介绍其工作原理： 1. 注册 Service Worker： Service W。","sidebarWeight":19,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/BOM/浏览器消息推送.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/浏览器消息推送.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/浏览器消息推送.md"}'),s={name:"posts/JavaScript系统教程/04-浏览器与 Web API/浏览器消息推送.md"};function a(c,e,p,n,l,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<div><h1 id="浏览器消息推送" tabindex="-1">浏览器消息推送 <a class="header-anchor" href="#浏览器消息推送" aria-label="Permalink to &quot;浏览器消息推送&quot;">​</a></h1><blockquote><p>本节目标：理解“浏览器消息推送”的核心思路，并能把它用于实际开发或面试表达。 浏览器消息推送，也称为 Web 推送通知，是一种能让网站向用户即时发送信息的技术，即使用户没有打开该网站的页面。这种技术主要依赖于浏览器的 Service Worker 和 Push API。下面详细介绍其工作原理：</p></blockquote><ol><li><p><strong>注册 Service Worker：</strong> Service Worker 是一种在浏览器背后运行的脚本，能够在页面未打开的情况下接收消息。首先，网站需要注册一个 Service Worker，这通常在用户同意接收通知后进行。Service Worker 负责监听来自推送服务的消息，并决定如何响应这些消息。</p></li><li><p><strong>用户订阅通知：</strong> 用户需要订阅通知，这通常通过显示一个弹窗让用户选择是否希望从网站接收通知。如果用户同意，浏览器会生成一个推送订阅，其中包括用于向该用户发送消息的唯一标识符（即订阅端点 URL）和一些密钥。</p></li><li><p><strong>发送订阅到服务器：</strong> 订阅信息被发送到网站的后端服务器，并存储起来。当需要向用户发送通知时，后端服务将使用这些信息。</p></li><li><p><strong>使用推送服务发送通知：</strong> 当网站想要发送一条通知时，它的服务器会向相应的推送服务（如谷歌的 FCM、苹果的 APNs 或其他）发送一个请求，包括订阅的端点 URL 和通知的详细信息。推送服务随后将这条信息传递给正确的浏览器。</p></li><li><p><strong>Service Worker 接收通知：</strong> 用户的浏览器收到来自推送服务的消息后，会激活对应的 Service Worker，Service Worker 通过 <code>push</code> 事件监听器接收到这个消息。</p></li><li><p><strong>展示通知：</strong> Service Worker 处理 <code>push</code> 事件，并使用浏览器的通知 API 展示一条通知。这个通知会在用户的设备上显示，即使他们当前没有打开发送通知的网站。</p></li><li><p><strong>交互和反馈：</strong> 用户可以与通知进行交互（如点击），这将触发 Service Worker 中的 <code>notificationclick</code> 事件。网站可以根据需要处理这些交互，例如打开一个新标签页或执行其他动作。</p></li></ol><p>整个流程实现了即使在网站未打开的情况下，也能将信息实时传达给用户。这种技术广泛用于新闻更新、聊天应用、邮件通知等场景。</p></div>',1)])])}const v=r(s,[["render",a]]);export{S as __pageData,v as default};
